import React, { useState } from "react";
import { useParams, useHistory } from "react-router-dom";
import { addUser } from "../../services/ApiUser";

const CardAddAdmin = () => {
  const { agenceId } = useParams();
  const history = useHistory();

  const [formData, setFormData] = useState({
    username: "",
    email: "",
    password: "",
    age: "",
    user_image: null,
  });

  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    if (name === "user_image") {
      setFormData({ ...formData, user_image: files[0] });
    } else {
      setFormData({ ...formData, [name]: value });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const validationErrors = {};
    if (!formData.username.trim()) validationErrors.username = "Nom requis";
    if (!formData.email.trim()) validationErrors.email = "Email requis";
    if (!formData.password.trim()) validationErrors.password = "Mot de passe requis";
    if (!formData.age || parseInt(formData.age) < 18 || parseInt(formData.age) > 100) {
      validationErrors.age = "Âge entre 18 et 100 requis";
    }

    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }

    try {
      const data = new FormData();
      data.append("username", formData.username);
      data.append("email", formData.email);
      data.append("password", formData.password);
      data.append("age", formData.age);
      data.append("role", "admin");
      data.append("agence", agenceId);
      if (formData.user_image) {
        data.append("user_image", formData.user_image);
      }

      await addUser(data);
      alert("Administrateur ajouté avec succès !");
      history.push("/admin/Agence");
    } catch (error) {
      console.error(error);
      alert("Erreur lors de l'ajout de l'administrateur.");
    }
  };

  return (
    <div className="relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded-lg bg-white border-0">
      <div className="rounded-t bg-white mb-0 px-6 py-6">
        <div className="text-center flex justify-between">
          <h6 className="text-blueGray-700 text-xl font-bold">Ajouter un administrateur</h6>
          <button
            className="bg-blue-500 text-white font-bold uppercase text-xs px-4 py-2 rounded shadow hover:shadow-md"
            type="button"
            onClick={() => history.push("/admin/Agence")}
          >
            Retour
          </button>
        </div>
      </div>

      <div className="flex-auto px-4 lg:px-10 py-10 pt-0">
        <form onSubmit={handleSubmit} encType="multipart/form-data">
          <div className="flex flex-wrap">
            {/* Username */}
            <div className="w-full lg:w-6/12 px-4 mb-4">
              <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                Nom d'utilisateur
              </label>
              <input
                type="text"
                name="username"
                value={formData.username}
                onChange={handleChange}
                className={`w-full px-3 py-2 rounded shadow text-sm ${
                  errors.username ? "border border-red-500" : "border"
                }`}
                placeholder="Nom d'utilisateur"
              />
              {errors.username && <p className="text-red-500 text-xs italic mt-1">{errors.username}</p>}
            </div>

            {/* Email */}
            <div className="w-full lg:w-6/12 px-4 mb-4">
              <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                Adresse email
              </label>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                className={`w-full px-3 py-2 rounded shadow text-sm ${
                  errors.email ? "border border-red-500" : "border"
                }`}
                placeholder="exemple@mail.com"
              />
              {errors.email && <p className="text-red-500 text-xs italic mt-1">{errors.email}</p>}
            </div>

            {/* Mot de passe */}
            <div className="w-full lg:w-6/12 px-4 mb-4">
              <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                Mot de passe
              </label>
              <input
                type="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
                className={`w-full px-3 py-2 rounded shadow text-sm ${
                  errors.password ? "border border-red-500" : "border"
                }`}
                placeholder="••••••••"
              />
              {errors.password && <p className="text-red-500 text-xs italic mt-1">{errors.password}</p>}
            </div>

            {/* Âge */}
            <div className="w-full lg:w-6/12 px-4 mb-4">
              <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                Âge
              </label>
              <input
                type="number"
                name="age"
                value={formData.age}
                onChange={handleChange}
                className={`w-full px-3 py-2 rounded shadow text-sm ${
                  errors.age ? "border border-red-500" : "border"
                }`}
                placeholder="Âge"
              />
              {errors.age && <p className="text-red-500 text-xs italic mt-1">{errors.age}</p>}
            </div>

            {/* Image */}
            <div className="w-full px-4 mb-4">
              <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                Photo de profil
              </label>
              <input
                type="file"
                name="user_image"
                accept="image/*"
                onChange={handleChange}
                className="w-full text-sm"
              />
            </div>
          </div>

          {/* Bouton d'envoi bien visible */}
          <div className="text-center mt-6">
            <button
              type="submit"
              className="bg-blue-600 text-white font-bold uppercase text-sm px-6 py-3 rounded-lg shadow hover:bg-blue-700 transition duration-150"
            >
              Ajouter l'admin
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default CardAddAdmin;
